# ---- the alignment engine (E2/E5/G1's), on the family code's spec/run/retold pairs --------------------------------------
def norm(w):
    w = re.sub(r'^ו', '', w); w = re.sub(r'^[הלכב]', '', w) if len(w) > 3 else w
    return w
def bagt(ws): return collections.Counter(norm(w) for w in ws)
def jact(a, b):
    A, B = bagt(a), bagt(b); i = sum((A & B).values()); u = sum((A | B).values()); return round(i / u, 2) if u else 0
def delta(spec, run):
    A, B = bagt(spec), bagt(run); return (sorted((B - A).elements()), sorted((A - B).elements()))
T = toks
def R_(book, ch, a, z):
    out = []
    for v in range(a, z + 1): out += T(book, ch, v)
    return out
A_COMMISSION = delta(R_('Gen', 24, 3, 8), R_('Gen', 24, 37, 41)); J_COMMISSION = jact(R_('Gen', 24, 3, 8), R_('Gen', 24, 37, 41))
A_PRAYER = delta(R_('Gen', 24, 12, 14), R_('Gen', 24, 42, 44)); J_PRAYER = jact(R_('Gen', 24, 12, 14), R_('Gen', 24, 42, 44))
A_WELL = delta(R_('Gen', 24, 17, 20), R_('Gen', 24, 45, 46))
A_QUESTION = delta(R_('Gen', 24, 22, 24), T('Gen', 24, 47))
A_PLEDGE = delta(T('Gen', 38, 18), T('Gen', 38, 25))
A_DEED_49 = delta(R_('Gen', 23, 17, 20), R_('Gen', 49, 29, 32)); J_DEED_49 = jact(R_('Gen', 23, 17, 20), R_('Gen', 49, 29, 32))
J_DEED_50 = jact(R_('Gen', 23, 17, 20), T('Gen', 50, 13)); J_DEED_25 = jact(R_('Gen', 25, 9, 10), T('Gen', 50, 13))
A_LEVIRATE = delta(T('Gen', 38, 8), R_('Deut', 25, 5, 6))
A_FIRSTBORN = delta(T('Gen', 49, 3), T('Deut', 21, 17))
A_ADOPTION = delta(T('Gen', 48, 5), R_('1Chr', 5, 1, 2))
A_BURIAL = delta(R_('Gen', 49, 29, 32), R_('Gen', 50, 12, 13))
A_KAF = delta(T('Gen', 32, 26), T('Gen', 32, 33))
A_RENAME_17_32 = delta(T('Gen', 17, 5), T('Gen', 32, 29)); A_RENAME_32_35 = delta(T('Gen', 32, 29), T('Gen', 35, 10))
