# ---- (3)+(5) run, grade, effects ------------------------------------
n = len(TESTS)
assert n == GUARDED, (n, GUARDED)
print('guard: %d test rows, every expected value a literal from the answer sheet [honest-pairing guard satisfied]' % GUARDED)
print()
ok = 0
frac = {I: 0, M: 0, A: 0, D: 0, P: 0, H: 0}
used = []
misses = []
for name, c, want in TESTS:
    hit = c['v'] == want
    ok += hit
    frac[c['p']] += 1
    used += [e for e in c['fx'] if e != FX.NONE]
    if not hit: misses.append((name, c['v']))
    print('%s %-96s [%s] %s' % ('OK ' if hit else 'MISS', name[:96], c['p'], '' if hit else 'got=%r' % (c['v'],)))
    print('     effects: %s' % ', '.join(c['fx']))
print()
print('MATRIX: %d/%d cells match the answer sheet' % (ok, n))
print('FRACTIONS: pure ink %d/%d (%d%%) · recorded moves %d/%d (%d%%) · answer-sheet %d/%d · data %d/%d · imports %d/%d · hypotheses %d/%d'
      % (frac[I], n, 100 * frac[I] // n, frac[M], n, 100 * frac[M] // n, frac[A], n, frac[D], n, frac[P], n, frac[H], n))
ops = FX.summarize(used)
print('LEDGER OPS this span writes: %s' % ', '.join('%s x%d' % kv for kv in sorted(ops.items())))
print('effects: every cell carries REGISTERED effects — TWENTY-EIGHT discovered in these verses\' own verbs: field_acquired, gifts_given, handed_to_the_agent, portion_added, birthright_transferred (TRANSFER); '
      'grave_holding, buried, dead_before_him, sworn_by_the_name, agent_commissioned, consent_given, wife_taken, comforted, pledge_held, sentence_pronounced, acquitted, firstborn_by_the_head, '
      'adopted_as_sons, younger_set_first, demoted, scattered_in_israel, scepter_held, gathered_to_his_people (STATUS); sinew_barred (BLOCK); levirate_owed, waits_for_the_levir, burial_owed (DEBIT); '
      'slain_by_heaven (HEAVEN) [effects law satisfied]')
print('SCENE: %r — the purchase, the match, the sinew, Judah\'s house with Tamar\'s timer fired and closed, the adoption and the testament, the burial owed and paid' % (SCENE,))
if ok == n:
    print('THE FAMILY CODE COMPILED — the purchase runs the three modes of acquiring land; the commission a spec/run/retold triple whose deltas the sugyot read; the sinew the one law with no '
          'Sinai seat; the levirate\'s first seat carrying the answer sheet\'s refused plea and its name resolved from the adoption\'s verse; the testament in the gift form; THIRTEEN engines CALLED.')
else:
    print('MISSES (%d):' % len(misses))
    for m_ in misses: print('  -', m_[0][:80], '->', m_[1])
    sys.exit('MISSES REMAIN — consult the Talmud per gap and recompile.')
